"""Parsing shipments from text."""
from shipments import Shipment


def _parse_line(line):
    route, weight = line.split(",")
    return Shipment(route.strip(), int(weight))


def parse_shipments(text):
    """Parse lines of 'route,weight' into Shipment records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out


def route_names(shipments):
    """Return the distinct route values, in first-seen order."""
    names = []
    for x in shipments:
        if x.route not in names:
            names.append(x.route)
    return names


def group_by_route(shipments):
    """Return a dict from route to the list of shipments with that route."""
    groups = {}
    for x in shipments:
        groups.setdefault(x.route, []).append(x)
    return groups

